param([string]$Solution='SanSo.V10.slnx')
$ErrorActionPreference='Stop';$xml=[xml](Get-Content -LiteralPath $Solution -Raw -Encoding UTF8);$projects=@($xml.Solution.Folder.Project|ForEach-Object{[string]$_.Path});$findings=@();foreach($project in $projects){$json=dotnet list $project package --vulnerable --include-transitive --format json;if($LASTEXITCODE-ne0){throw "VULNERABILITY_SCAN_COMMAND_FAILED:$project"};if(($json-join[Environment]::NewLine)-match '"severity"\s*:'){$findings+=$project}};if($findings.Count){throw "DOTNET_VULNERABILITIES_FOUND:$($findings.Count):$($findings-join',')"};"DOTNET_VULNERABILITY_SCAN_PASSED projects=$($projects.Count)"
